#nullable enable // autogenerated

using MVZ2.GameContent.Customize;
using MVZ2.GameContent.Seeds;
using MVZ2.GameContent.Stages;
using MVZ2.Saves;
using MVZ2.Vanilla.Saves;
using MVZ2.Vanilla.Stats;
using MVZ2.Vanilla.Unlocks;
using MVZ2Logic;
using MVZ2Logic.Blueprints;
using MVZ2Logic.Games;
using MVZ2Logic.Level;
using MVZ2Logic.Modding;
using MVZ2Logic.Saves;
using MVZ2Logic.Serialization;
using PVZEngine;
using PVZEngine.Level;
using PVZEngine.SeedPacks;

namespace MVZ2.Vanilla
{
    public class VanillaMod : Mod, IVanillaInterface
    {
        public VanillaMod() : base(spaceName)
        {
        }
        public override void PreInit(IModLoader modLoader)
        {
            base.PreInit(modLoader);
            modLoader.AddSeedDefinitionProvider(new EntitySeedProvider());
            modLoader.AddStageDefinitionProvider(new StageDefinitionProvider());
        }
        public override void OnInit(IGlobalGame game)
        {
            base.OnInit(game);
            Global.SetVanillaInterface(this);
            RegisterSerializableType<SerializableVanillaSaveData>();
            RegisterSerializableType<TeleporterTeamLevelData>();
            RegisterSerializableType<TeleporterTeamTileLevelData>();
        }

        #region 存档
        public override ModSaveData CreateSaveData()
        {
            return new VanillaSaveData(spaceName);
        }
        public override string SerializeSaveData(ModSaveData saveData)
        {
            var seri = saveData.ToSerializable();
            seri.version = SAVE_DATA_VERSION;
            return seri.ToBson();
        }
        public override ModSaveData DeserializeSaveData(string json)
        {
            var serializableLogic = Deserialize<SerializableVanillaSaveData>(json);
            if (serializableLogic.version > SAVE_DATA_VERSION)
                throw new NewerSaveDataException();
            return VanillaSaveData.DeserializeFrom(serializableLogic);
        }
        public override void PostAllSaveDataLoaded()
        {
            // 通过梦境世界第7关，并且没有通过第11关。
            var saves = Global.Saves;
            if (saves.IsUnlocked(VanillaUnlockID.dream7) && !saves.IsUnlocked(VanillaUnlockID.dream11))
            {
                saves.Unlock(VanillaUnlockID.dreamIsNightmare);
            }
        }
        #endregion

        #region IVanillaInterface实现
        public bool IsEnemyEncountered(IGlobalSaveData saves, NamespaceID enemyID)
        {
            return saves.GetStat(VanillaStats.CATEGORY_ENEMY_NEUTRALIZE, enemyID) > 0;
        }
        #endregion

        public const int SAVE_DATA_VERSION = 1;
        public const float INSTA_DAMAGE_AMOUNT = 58115310;
        public const string spaceName = "mvz2";

        #region 内嵌类
        public class EntitySeedProvider : ISeedDefinitionProvider
        {
            public bool TryHandle(string nsp, string id, SeedParameters parameters, out SeedDefinition result)
            {
                result = new EntitySeed(nsp, id, parameters);
                return true;
            }
            public int Priority { get; set; } = 0;
        }
        public class StageDefinitionProvider : IStageDefinitionProvider
        {

            public bool TryHandle(string type, string nsp, string id, out StageDefinition? result)
            {
                switch (type)
                {
                    case StageTypes.TYPE_NORMAL:
                        result = new ClassicStage(nsp, id);
                        return true;
                    case StageTypes.TYPE_ENDLESS:
                        result = new EndlessStage(nsp, id);
                        return true;
                }
                result = null;
                return false;
            }
            public int Priority { get; set; } = 0;
        }
        #endregion
    }
}
